library(tidyverse)
args <- commandArgs(trailingOnly=FALSE)
script <- normalizePath(sub('^--file=', '', args[grepl('^--file=', args)][1]))
b <- dirname(dirname(script))
a <- read_csv(file.path(b,'all_industry_results.csv'),show_col_types=FALSE) %>% filter(specification=='matched_pair_year',metric=='log')
labels <- a %>% distinct(sector,industry) %>% arrange(sector) %>% pull(industry)
a <- a %>% mutate(Industry=factor(industry,levels=rev(labels)),Perspective=factor(perspective,levels=c('RAC','WAC'),labels=c('RAC: jobs held by residents','WAC: jobs located in the tract')))
p <- ggplot(a,aes(100*estimate,Industry))+geom_vline(xintercept=0,color='grey55')+geom_errorbar(aes(xmin=100*ci_low,xmax=100*ci_high),orientation='y',width=.15,color='#2B5685')+geom_point(color='#2B5685',size=2,shape=16)+facet_grid(.~Perspective)+theme_bw(base_size=11)+theme(panel.grid.minor=element_blank(),plot.margin=margin(12,15,12,12))+labs(x='100 × effect on log employment',y=NULL)
ggsave(file.path(b,'paper_preview','industry_log_rac_wac.png'),p,width=13,height=8.5,dpi=200)
